function PublicFooter() { const { t } = useLanguage(); return <footer className="bg-sidebar px-4 py-12 text-sidebar-foreground md:px-8"><div className="mx-auto grid max-w-7xl gap-10 md:grid-cols-[1.3fr_1fr_1fr_1fr]"><div><span className="text-lg font-bold">HiMe <span className="text-[#f2c66d]">AI</span></span><p className="mt-4 max-w-xs text-sm leading-7 text-sidebar-foreground/60">مساحة أكثر وضوحاً للقرارات المهنية المهمة.</p></div><div><p className="mb-4 text-xs font-bold uppercase tracking-widest text-[#f2c66d]">المنصة</p><div className="space-y-3 text-sm text-sidebar-foreground/70"><Link href="/jobs" className="block hover:text-white" data-testid="link-footer-jobs">{t('navJobs')}</Link><Link href="/about" className="block hover:text-white" data-testid="link-footer-about">{t('navAbout')}</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-widest text-[#f2c66d]">للباحثين</p><div className="space-y-3 text-sm text-sidebar-foreground/70"><Link href="/register" className="block hover:text-white" data-testid="link-footer-seeker">{t('seeker')}</Link><Link href="/seeker/cv" className="block hover:text-white" data-testid="link-footer-cv">{t('cv')}</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-widest text-[#f2c66d]">للشركات</p><div className="space-y-3 text-sm text-sidebar-foreground/70"><Link href="/register" className="block hover:text-white" data-testid="link-footer-company">{t('company')}</Link><Link href="/company/jobs/new" className="block hover:text-white" data-testid="link-footer-post">{'أضف وظيفة'}</Link></div></div></div><div className="mx-auto mt-12 max-w-7xl border-t border-sidebar-border pt-5 text-xs text-sidebar-foreground/50">© 2025 HiMe AI · قرارك المهني يستحق معلومات أفضل</div></footer>; }

export function HomePage() { const { t } = useLanguage(); return <div className="grain"><PublicNav /><main><section className="surface-grid relative overflow-hidden"><div className="mx-auto grid min-h-[620px] max-w-7xl items-center gap-12 px-4 py-20 md:grid-cols-[1.1fr_.9fr] md:px-8 md:py-28"><div className="animate-rise"><p className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary/20 bg-primary/5 px-3 py-1.5 text-xs font-bold text-primary"><span className="h-2 w-2 rounded-full bg-accent" />{t('homeEyebrow')}</p><h1 className="max-w-3xl text-4xl font-bold leading-[1.25] tracking-tight text-balance md:text-6xl">{t('homeTitle')}</h1><p className="mt-6 max-w-xl text-base leading-8 text-muted-foreground md:text-lg">{t('homeBody')}</p><div className="mt-9 flex flex-col gap-3 sm:flex-row"><Link href="/register" className="inline-flex items-center justify-center gap-2 rounded-lg bg-primary px-5 py-3.5 text-sm font-bold text-primary-foreground shadow-lg shadow-primary/15 hover:opacity-90" data-testid="link-hero-seeker">{t('seeker')} <ArrowUpLeft className="h-4 w-4" /></Link><Link href="/register" className="inline-flex items-center justify-center gap-2 rounded-lg border border-primary/30 bg-card px-5 py-3.5 text-sm font-bold text-primary hover:bg-primary/5" data-testid="link-hero-company">{t('company')} <ArrowUpLeft className="h-4 w-4" /></Link></div><div className="mt-9 flex items-center gap-6 text-xs text-muted-foreground"><span className="inline-flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-primary" />بياناتك ملكك</span><span className="inline-flex items-center gap-2"><HeartHandshake className="h-4 w-4 text-primary" />قرارات أكثر إنصافاً</span></div></div><div className="relative animate-rise delay-2"><div className="absolute -inset-10 rounded-full bg-accent/10 blur-3xl" /><Card className="relative overflow-hidden border-primary/20 bg-card/90 p-2 shadow-2xl shadow-primary/10"><div className="rounded-xl bg-sidebar p-6 text-sidebar-foreground md:p-8"><div className="mb-8 flex items-center justify-between"><div><p className="text-xs text-sidebar-foreground/60">نتيجة المطابقة</p><p className="mt-1 text-lg font-bold">مصمم تجربة مستخدم أول</p></div><span className="rounded-full bg-[#f2c66d]/15 px-3 py-1.5 text-xs font-bold text-[#f2c66d]">مقترحة لك</span></div><div className="flex items-center gap-6"><ScoreRing score={92} size="lg" /><div className="flex-1 space-y-4">{[['المهارات', 94], ['الخبرة', 90], ['السياق العام', 95]].map(([label, score]) => <div key={label as string}><div className="mb-1 flex justify-between text-xs"><span className="text-sidebar-foreground/70">{label}</span><span className="font-bold text-[#f2c66d]">{score}%</span></div><div className="h-1.5 rounded-full bg-white/10"><div className="h-full rounded-full bg-[#f2c66d]" style={{ width: `${score}%` }} /></div></div>)}</div></div><div className="mt-8 rounded-xl border border-white/10 bg-white/5 p-4"><p className="text-xs leading-6 text-sidebar-foreground/70">«خبرتك في البحث وتصميم الأنظمة تتوافق بقوة مع احتياج الفريق.»</p></div></div></Card><div className="absolute -bottom-5 -start-5 rounded-xl border border-border bg-card p-4 shadow-xl"><p className="text-[10px] text-muted-foreground">ملفك المهني</p><div className="mt-1 flex items-center gap-2"><div className="h-2 w-20 rounded-full bg-primary" /><span className="text-xs font-bold text-primary">82%</span></div></div></div></div></section><section className="mx-auto max-w-7xl px-4 py-24 md:px-8"><div className="max-w-xl"><p className="mb-3 text-xs font-bold uppercase tracking-[.2em] text-primary">{t('how')}</p><h2 className="text-3xl font-bold tracking-tight md:text-4xl">من سيرتك الذاتية إلى خطوة مفهومة.</h2></div><div className="mt-14 grid gap-5 md:grid-cols-3">{[['01', 'ابنِ ملفاً يعكسك', 'أضف خبرتك، مهاراتك، وتفضيلاتك. لا تحتاج إلى أن تكون خبيراً في كتابة السير الذاتية.'], ['02', 'دع الذكاء يرتّب الصورة', 'نحلل التقاطع بين ملفك واحتياجات الدور، ونشرح لك عناصر القوة والفجوات.'], ['03', 'اتخذ قرارك بثقة', 'استكشف الفرص، تقدّم، وتابع مسارك من مساحة واحدة دون ضجيج.']].map(([num, title, body]) => <div key={num} className="rounded-2xl border border-border bg-card p-6"><span className="font-mono text-sm text-accent">{num}</span><h3 className="mt-12 text-lg font-bold">{title}</h3><p className="mt-3 text-sm leading-7 text-muted-foreground">{body}</p></div>)}</div></section><section className="bg-secondary/50 px-4 py-24 md:px-8"><div className="mx-auto max-w-7xl"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="mb-3 text-xs font-bold uppercase tracking-[.2em] text-primary">{t('features')}</p><h2 className="max-w-xl text-3xl font-bold tracking-tight md:text-4xl">تقنية تعمل بهدوء، في اللحظة التي تحتاجها.</h2></div><Link href="/about" className="text-sm font-bold text-primary" data-testid="link-home-about">{t('navAbout')} <ArrowUpLeft className="inline h-4 w-4" /></Link></div><div className="mt-14 grid gap-5 md:grid-cols-12"><Card className="md:col-span-7 bg-sidebar text-sidebar-foreground"><CardContent className="p-7 md:p-9"><Sparkles className="h-7 w-7 text-[#f2c66d]" /><h3 className="mt-12 text-2xl font-bold">مطابقة تشرح نفسها</h3><p className="mt-3 max-w-md text-sm leading-7 text-sidebar-foreground/70">لا نرمي رقماً مجرداً. ترى كيف تجمّعت النتيجة، ما الذي يطابقك، وما الذي يستحق التطوير.</p><div className="mt-8 flex flex-wrap gap-2">{['مهاراتك', 'خبرتك', 'مشاريعك', 'السياق'].map((x) => <span key={x} className="rounded-full border border-white/10 px-3 py-1.5 text-xs text-sidebar-foreground/70">{x}</span>)}</div></CardContent></Card><Card className="md:col-span-5"><CardContent className="p-7 md:p-9"><Target className="h-7 w-7 text-primary" /><h3 className="mt-12 text-xl font-bold">وجهة واحدة لمسارك</h3><p className="mt-3 text-sm leading-7 text-muted-foreground">من أول رفع السيرة إلى متابعة طلباتك، كل خطوة في مكان واضح.</p><div className="mt-7 flex items-center gap-3 text-xs font-semibold"><div className="grid h-8 w-8 place-items-center rounded-lg bg-primary/10 text-primary"><Check className="h-4 w-4" /></div>تقدّم يعرف أين يقف</div></CardContent></Card></div></div></section><section className="mx-auto max-w-7xl px-4 py-24 md:px-8"><div className="grid items-center gap-12 md:grid-cols-2"><div><p className="mb-3 text-xs font-bold uppercase tracking-[.2em] text-primary">لست رقماً</p><h2 className="text-3xl font-bold tracking-tight md:text-4xl">وظيفة مناسبة تبدأ بفهم أفضل.</h2><p className="mt-5 leading-8 text-muted-foreground">نصمم HiMe AI للناس خلف الملفات الشخصية: للباحث الذي يريد أن يُرى بوضوح، وللفريق الذي يريد أن يختار بعدل ووعي.</p><Link href="/jobs" className="mt-8 inline-flex items-center gap-2 text-sm font-bold text-primary" data-testid="link-home-jobs">{t('navJobs')} <ArrowUpLeft className="h-4 w-4" /></Link></div><div className="grid grid-cols-2 gap-3"><div className="rounded-2xl bg-primary p-6 text-primary-foreground"><p className="text-4xl font-bold">92%</p><p className="mt-2 text-xs opacity-75">مثال على تطابق قابل للفهم</p></div><div className="rounded-2xl border border-border bg-card p-6"><p className="text-4xl font-bold text-accent">6</p><p className="mt-2 text-xs text-muted-foreground">أبعاد نستخدمها في الشرح</p></div><div className="col-span-2 rounded-2xl bg-accent/15 p-6"><p className="text-sm font-bold">دعم قرار، لا قرار نهائي</p><p className="mt-2 text-xs leading-6 text-muted-foreground">الذكاء الاصطناعي يساعدك على رؤية الصورة، وأنت صاحب القرار.</p></div></div></div></section></main><PublicFooter /></div>; }

export function JobsPage() { const { t } = useLanguage(); const [search, setSearch] = useState(''); const [industry, setIndustry] = useState(''); const [contract, setContract] = useState(''); const { data, loading, error, reload } = useDemo(() => demoApi.listJobs({ search, industry, contract }), [search, industry, contract]); const jobs = data || []; return <><PublicNav /><main className="mx-auto max-w-7xl px-4 py-10 md:px-8 md:py-16"><PageHeader eyebrow="سوق الفرص" title="ابحث عن الدور الذي يليق بخطوتك." description="فرص منتقاة مع سياق واضح، لا قوائم لا تنتهي." /><div className="mb-8 grid gap-3 rounded-2xl border border-border bg-card p-3 md:grid-cols-[1fr_180px_160px_auto]"><label className="relative"><Search className="absolute start-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="h-10 ps-10" value={search} onChange={(e) => setSearch(e.target.value)} placeholder={t('search')} data-testid="input-job-search" /></label><select value={industry} onChange={(e) => setIndustry(e.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm" data-testid="select-industry"><option value="">كل الصناعات</option><option>تقنية المعلومات</option><option>التقنية المالية</option><option>الاستشارات</option></select><select value={contract} onChange={(e) => setContract(e.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm" data-testid="select-contract"><option value="">كل العقود</option><option value="full-time">دوام كامل</option><option value="contract">عقد مستقل</option></select><Button variant="secondary" onClick={() => { setSearch(''); setIndustry(''); setContract(''); }} data-testid="button-reset-filters"><SlidersHorizontal className="h-4 w-4" />إعادة ضبط</Button></div>{loading ? <LoadingState /> : error ? <FeedbackState error={error} retry={reload} /> : jobs.length === 0 ? <EmptySearch onClear={() => { setSearch(''); setIndustry(''); setContract(''); }} /> : <><div className="mb-4 flex items-center justify-between text-sm text-muted-foreground"><span>{jobs.length} فرص متاحة</span><button className="inline-flex items-center gap-1" data-testid="button-sort-jobs">الأحدث <ChevronDown className="h-4 w-4" /></button></div><div className="grid gap-4 md:grid-cols-2">{jobs.map((job) => <JobCard key={job.id} job={job} />)}</div></>}</main></>; }

export function JobDetailsPage() { const { id } = useParams<{ id: string }>(); const [, setLocation] = useLocation(); const { t } = useLanguage(); const { data: job, loading, error, reload } = useDemo(() => demoApi.getJob(id || ''), [id]); const [status, setStatus] = useState(''); const apply = async () => { if (!job) return; await demoApi.apply(job.id); setStatus('تم إرسال طلبك بنجاح'); }; if (loading) return <><PublicNav /><main className="mx-auto max-w-5xl px-4 py-16"><LoadingState /></main></>; if (error || !job) return <><PublicNav /><main className="mx-auto max-w-5xl px-4 py-16"><FeedbackState error={error || 'الوظيفة غير موجودة'} retry={reload} /></main></>; return <><PublicNav /><main className="mx-auto max-w-6xl px-4 py-10 md:px-8 md:py-16"><Link href="/jobs" className="mb-8 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground" data-testid="link-back-jobs"><ArrowDownLeft className="h-4 w-4" />العودة للوظائف</Link><div className="grid gap-8 lg:grid-cols-[1fr_320px]"><div><div className="mb-8 flex gap-4"><div className="grid h-16 w-16 shrink-0 place-items-center rounded-2xl bg-secondary text-primary"><BriefcaseBusinessIcon /></div><div><h1 className="text-3xl font-bold">{job.title}</h1><p className="mt-2 text-muted-foreground">{job.company.name} · {job.location}</p><div className="mt-4 flex flex-wrap gap-2"><span className="rounded-full bg-muted px-3 py-1 text-xs">{job.experience}</span><span className="rounded-full bg-muted px-3 py-1 text-xs">{job.contract}</span><span className="rounded-full bg-muted px-3 py-1 text-xs">{job.industry}</span></div></div></div><section className="prose prose-sm max-w-none"><h2>عن الدور</h2><p>{job.description}</p><h2>المهارات المطلوبة</h2><div className="not-prose flex flex-wrap gap-2">{job.requiredSkills.map((s) => <span key={s.id} className="rounded-lg bg-primary/10 px-3 py-2 text-xs font-semibold text-primary">{s.name}</span>)}</div><h2>المهارات المفضلة</h2><div className="not-prose flex flex-wrap gap-2">{job.preferredSkills.map((s) => <span key={s.id} className="rounded-lg bg-muted px-3 py-2 text-xs">{s.name}</span>)}</div><h2>المؤهلات</h2><p>{job.education}</p></section></div><aside><Card className="sticky top-24"><CardContent className="p-6"><p className="text-xs text-muted-foreground">النطاق المتوقع</p><p className="mt-1 text-lg font-bold">{job.salary}</p><div className="my-5 space-y-3 border-y border-border py-5 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">آخر موعد</span><span>{job.deadline}</span></div><div className="flex justify-between"><span className="text-muted-foreground">المتقدمون</span><span>{job.applicants}</span></div></div>{status ? <div className="rounded-lg bg-primary/10 p-3 text-center text-sm font-semibold text-primary" data-testid="status-application-success"><CheckCircle2 className="mx-auto mb-1 h-5 w-5" />{status}</div> : <Button className="w-full" onClick={apply} data-testid="button-apply-job">{t('apply')} <ArrowUpLeft className="h-4 w-4" /></Button>}<p className="mt-3 text-center text-[11px] text-muted-foreground">سيتم ربط التقديم بحسابك عند تسجيل الدخول.</p></CardContent></Card></aside></div></main></>; }
function BriefcaseBusinessIcon() { return <BriefcaseBusiness className="h-7 w-7" />; }

export function LoginPage() { const { t } = useLanguage(); const [submitted, setSubmitted] = useState(false); return <AuthFrame title="مرحباً بعودتك" subtitle="مساحتك المهنية، كما تركتها." side="رؤيتك المهنية تستحق مساحة واضحة."><form onSubmit={(e) => { e.preventDefault(); setSubmitted(true); }} className="space-y-5"><Field label="البريد الإلكتروني" value="" onChange={() => undefined} placeholder="name@example.com" /><Field label="كلمة المرور" value="" onChange={() => undefined} placeholder="••••••••" /><div className="flex items-center justify-between text-xs"><label className="flex items-center gap-2"><input type="checkbox" data-testid="checkbox-remember" /> تذكرني</label><button type="button" className="font-bold text-primary" data-testid="button-forgot-password">نسيت كلمة المرور؟</button></div><Button type="submit" className="w-full" data-testid="button-submit-login">{submitted ? 'تم التحقق من الطلب' : t('signIn')}</Button>{submitted && <p className="rounded-lg bg-primary/10 p-3 text-center text-xs text-primary" data-testid="status-login-success">سيتم ربط الدخول بواجهة الخادم عند جاهزية API.</p>}</form></AuthFrame>; }
export function RegisterPage() { const [role, setRole] = useState<'seeker' | 'company'>('seeker'); const [done, setDone] = useState(false); return <AuthFrame title="ابدأ من مكانك" subtitle="أنشئ مساحة تساعدك على الخطوة التالية." side="سواء كنت تبحث عن فرصة أو عن الشخص المناسب، ابدأ بمعلومة أوضح."><form onSubmit={(e) => { e.preventDefault(); setDone(true); }} className="space-y-4"><Field label="الاسم الكامل" value="" onChange={() => undefined} placeholder="اكتب اسمك" /><Field label="البريد الإلكتروني" value="" onChange={() => undefined} placeholder="name@example.com" /><Field label="كلمة المرور" value="" onChange={() => undefined} placeholder="8 أحرف على الأقل" /><div><p className="mb-2 text-sm font-semibold">نوع الحساب</p><div className="grid grid-cols-2 gap-2">{[['seeker', 'باحث عن عمل'], ['company', 'شركة']].map(([value, label]) => <button type="button" key={value} onClick={() => setRole(value as 'seeker' | 'company')} className={`rounded-lg border p-3 text-sm font-semibold ${role === value ? 'border-primary bg-primary/10 text-primary' : 'border-border'}`} data-testid={`button-role-${value}`}>{label}</button>)}</div></div><label className="flex items-start gap-2 text-xs leading-5 text-muted-foreground"><input type="checkbox" required data-testid="checkbox-terms" /> أوافق على شروط الاستخدام وسياسة الخصوصية.</label><Button type="submit" className="w-full" data-testid="button-submit-register">{done ? 'تم تجهيز طلبك' : 'إنشاء الحساب'}</Button>{done && <p className="rounded-lg bg-primary/10 p-3 text-center text-xs text-primary" data-testid="status-register-success">واجهة التسجيل جاهزة للربط مع API.</p>}</form></AuthFrame>; }
function AuthFrame({ title, subtitle, side, children }: { title: string; subtitle: string; side: string; children: ReactNode }) { return <div className="grid min-h-[100dvh] lg:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-sidebar p-12 text-sidebar-foreground lg:flex lg:flex-col lg:justify-between"><LogoLight /><div><p className="mb-5 text-xs uppercase tracking-[.2em] text-[#f2c66d]">HiMe AI</p><h1 className="max-w-md text-4xl font-bold leading-tight">{side}</h1><div className="mt-8 flex gap-3 text-sm text-sidebar-foreground/60"><ShieldCheck className="h-5 w-5 text-[#f2c66d]" />قرارات مهنية أكثر وعياً</div></div><p className="text-xs text-sidebar-foreground/50">بيئة تجريبية جاهزة للربط بواجهة REST.</p></div><div className="flex flex-col p-5 md:p-10"><div className="mb-16 flex items-center justify-between lg:justify-end"><Link href="/" className="lg:hidden" data-testid="link-auth-logo"><span className="font-bold">HiMe <span className="text-accent">AI</span></span></Link><Link href="/jobs" className="text-xs font-semibold text-muted-foreground" data-testid="link-auth-jobs">استكشف الوظائف <ArrowUpLeft className="inline h-3 w-3" /></Link></div><div className="mx-auto w-full max-w-md"><h2 className="text-3xl font-bold">{title}</h2><p className="mt-2 text-sm text-muted-foreground">{subtitle}</p><div className="mt-8">{children}</div><p className="mt-8 text-center text-xs text-muted-foreground">بالاستمرار، أنت توافق على سياسة الخصوصية وشروط الاستخدام.</p></div></div></div>; }
function LogoLight() { return <Link href="/" className="text-lg font-bold">HiMe <span className="text-[#f2c66d]">AI</span></Link>; }

export function AboutPage() { return <><PublicNav /><main><section className="bg-sidebar px-4 py-24 text-sidebar-foreground md:px-8 md:py-32"><div className="mx-auto max-w-5xl"><p className="mb-5 text-xs font-bold uppercase tracking-[.22em] text-[#f2c66d]">قصة HiMe AI</p><h1 className="max-w-3xl text-4xl font-bold leading-tight md:text-6xl">نؤمن أن أفضل قرار مهني يبدأ من رؤية الإنسان كاملاً.</h1><p className="mt-7 max-w-2xl text-base leading-8 text-sidebar-foreground/65">التوظيف لا يحتاج مزيداً من الضجيج. يحتاج لغة مشتركة بين الطموح والاحتياج، وأدوات تجعل ما وراء السيرة الذاتية قابلاً للفهم.</p></div></section><section className="mx-auto max-w-5xl px-4 py-20 md:px-8"><div className="grid gap-8 md:grid-cols-3"><div><p className="text-4xl font-bold text-primary">01</p><h2 className="mt-5 font-bold">وضوح قبل السرعة</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">نفضل نتيجة مفهومة على قائمة طويلة لا تساعدك على الاختيار.</p></div><div><p className="text-4xl font-bold text-accent">02</p><h2 className="mt-5 font-bold">الذكاء مع الإنسان</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">المطابقة دعم لاتخاذ القرار، وليست بديلاً عن الحكم البشري أو الحوار.</p></div><div><p className="text-4xl font-bold text-primary">03</p><h2 className="mt-5 font-bold">سياق عربي أصيل</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">نبني لغة وتجربة تحترم تفاصيل العمل في منطقتنا، من المصطلح إلى التوقع.</p></div></div><Card className="mt-20 bg-secondary/60"><CardContent className="grid gap-8 p-8 md:grid-cols-[1fr_1.3fr] md:p-12"><div><Sparkles className="h-8 w-8 text-primary" /><h2 className="mt-6 text-2xl font-bold">ثقة قابلة للمراجعة</h2></div><p className="text-sm leading-8 text-muted-foreground">نوضح ما استخرجته الأنظمة، ونذكّرك بمراجعته، ونحاول أن نجعل كل توصية قابلة للسؤال. لأن مسارك المهني ليس تجربة مغلقة.</p></CardContent></Card></section></main><PublicFooter /></>; }

export function SeekerDashboardPage() { const { t } = useLanguage(); const { data: profile, loading } = useDemo(demoApi.getProfile, []); const { data: jobs } = useDemo(() => demoApi.listJobs(), []); const { data: applications } = useDemo(demoApi.applications, []); if (loading || !profile) return <DashboardLayout role="seeker"><LoadingState /></DashboardLayout>; return <DashboardLayout role="seeker"><PageHeader eyebrow="مساحتك المهنية" title="مساء الخير، ليان." description="إليك ما يستحق انتباهك اليوم." action={<Link href="/seeker/profile" className="rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-dashboard-edit-profile">{t('profile')}</Link>} /><div className="grid gap-4 md:grid-cols-3"><Card className="md:col-span-2 bg-sidebar text-sidebar-foreground"><CardContent className="flex flex-col justify-between gap-6 p-6 md:flex-row md:items-center"><div><p className="text-xs text-sidebar-foreground/60">اكتمال الملف</p><p className="mt-2 text-3xl font-bold">{profile.completion}%</p><p className="mt-2 text-xs text-sidebar-foreground/60">أضف مشروعاً واحداً لتقوية ظهورك</p></div><div className="h-2 flex-1 rounded-full bg-white/10 md:max-w-[240px]"><div className="h-full rounded-full bg-[#f2c66d]" style={{ width: `${profile.completion}%` }} /></div><Link href="/seeker/profile" className="text-xs font-bold text-[#f2c66d]" data-testid="link-complete-profile">إكمال الملف <ArrowUpLeft className="inline h-3 w-3" /></Link></CardContent></Card><Card><CardContent className="p-6"><FileCheck2 className="h-6 w-6 text-primary" /><p className="mt-5 text-sm font-semibold">السيرة الذاتية</p><p className="mt-1 text-xs text-muted-foreground">تم تحليلها ويمكنك مراجعتها</p><Link href="/seeker/cv" className="mt-5 inline-block text-xs font-bold text-primary" data-testid="link-dashboard-cv">مراجعة الملف</Link></CardContent></Card></div><div className="mt-10 flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">مبني على ملفك</p><h2 className="mt-2 text-2xl font-bold">{t('jobs')}</h2></div><Link href="/seeker/recommendations" className="text-sm font-bold text-primary" data-testid="link-dashboard-recommendations">{t('viewAll')} <ArrowUpLeft className="inline h-4 w-4" /></Link></div><div className="mt-5 grid gap-4 md:grid-cols-2">{(jobs || []).slice(0, 2).map((job, i) => <JobCard key={job.id} job={job} match={[92, 87][i]} />)}</div><div className="mt-10 grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><Card><CardHeader><CardTitle className="text-base">{t('applications')}</CardTitle></CardHeader><CardContent><div className="grid grid-cols-3 gap-3 text-center">{[['2', 'الكل'], ['1', 'قيد المراجعة'], ['1', 'مختارة']].map(([n, label]) => <div key={label} className="rounded-xl bg-muted p-4"><p className="text-2xl font-bold text-primary">{n}</p><p className="mt-1 text-[11px] text-muted-foreground">{label}</p></div>)}</div>{applications?.slice(0, 1).map((application) => <div key={application.id} className="mt-5 flex items-center justify-between border-t border-border pt-4 text-sm"><span>{application.job.title}</span><span className="rounded-full bg-accent/15 px-2 py-1 text-xs font-semibold text-accent-foreground">قيد المراجعة</span></div>)}</CardContent></Card><Card><CardHeader><CardTitle className="text-base">آخر تطابق</CardTitle></CardHeader><CardContent><div className="flex items-center gap-5"><ScoreRing score={92} /><div><p className="font-bold">مصمم تجربة مستخدم أول</p><p className="mt-1 text-xs text-muted-foreground">تطابق قوي في المهارات والخبرة</p><Link href="/seeker/recommendations" className="mt-3 inline-block text-xs font-bold text-primary" data-testid="link-latest-match">شاهد التفاصيل</Link></div></div></CardContent></Card></div></DashboardLayout>; }

export function SeekerProfilePage() { const { data, loading } = useDemo(demoApi.getProfile, []); const [profile, setProfile] = useState<CandidateProfile | null>(null); const [saved, setSaved] = useState(false); if (loading || (!data && !profile)) return <DashboardLayout role="seeker"><LoadingState /></DashboardLayout>; const value = profile || data!; const update = (key: keyof CandidateProfile, next: string) => setProfile({ ...value, [key]: next }); return <DashboardLayout role="seeker"><PageHeader eyebrow="ملفك المهني" title="ملف يختصر قصتك دون أن يختزلك." description="تظهر هذه المعلومات في توصياتك وتساعد الشركات على فهم مسارك." action={<Button onClick={async () => { await demoApi.updateProfile(value); setSaved(true); }} data-testid="button-save-profile">{saved ? <CheckCircle2 className="h-4 w-4" /> : null}{saved ? 'تم الحفظ' : 'حفظ التغييرات'}</Button>} /><div className="grid gap-6 lg:grid-cols-[1fr_280px]"><div className="space-y-6"><Card><CardHeader><CardTitle className="text-base">المعلومات الأساسية</CardTitle></CardHeader><CardContent className="grid gap-5 md:grid-cols-2"><Field label="العنوان المهني" value={value.headline} onChange={(v) => update('headline', v)} /><Field label="الموقع" value={value.location} onChange={(v) => update('location', v)} /><div className="md:col-span-2"><Field label="نبذة مهنية" value={value.summary} onChange={(v) => update('summary', v)} multiline /></div></CardContent></Card><Card><CardHeader><CardTitle className="text-base">المهارات</CardTitle></CardHeader><CardContent><div className="flex flex-wrap gap-2">{value.skills.map((skill) => <span key={skill.id} className="inline-flex items-center gap-1 rounded-full bg-primary/10 px-3 py-1.5 text-xs font-semibold text-primary">{skill.name}<button aria-label={`remove ${skill.name}`} data-testid={`button-remove-skill-${skill.id}`}><X className="h-3 w-3" /></button></span>)}<button className="inline-flex items-center gap-1 rounded-full border border-dashed border-primary px-3 py-1.5 text-xs font-semibold text-primary" data-testid="button-add-skill"><Plus className="h-3 w-3" />إضافة مهارة</button></div></CardContent></Card><Card><CardHeader><CardTitle className="text-base">الخبرة والتعليم</CardTitle></CardHeader><CardContent className="space-y-5">{value.experiences.map((item) => <div key={item.id} className="flex gap-4"><div className="mt-1 h-2.5 w-2.5 rounded-full bg-accent" /><div><p className="text-sm font-bold">{item.role}</p><p className="mt-1 text-xs text-muted-foreground">{item.company} · {item.startDate} — {item.endDate}</p><p className="mt-2 text-xs leading-6 text-muted-foreground">{item.description}</p></div></div>)}{value.education.map((item) => <div key={item.id} className="flex gap-4 border-t border-border pt-5"><div className="mt-1 h-2.5 w-2.5 rounded-full bg-primary" /><div><p className="text-sm font-bold">{item.degree} · {item.field}</p><p className="mt-1 text-xs text-muted-foreground">{item.institution} · {item.year}</p></div></div>)}</CardContent></Card></div><Card className="h-fit bg-secondary/50"><CardContent className="p-6"><div className="flex items-center justify-between"><p className="text-sm font-bold">قوة الملف</p><span className="text-2xl font-bold text-primary">{value.completion}%</span></div><div className="mt-4 h-2 rounded-full bg-background"><div className="h-full rounded-full bg-primary" style={{ width: `${value.completion}%` }} /></div><p className="mt-4 text-xs leading-6 text-muted-foreground">ملفك واضح. إضافة مشروع حديث أو رابط أعمال قد يرفع فرص ظهوره.</p></CardContent></Card></div></DashboardLayout>; }

export function SeekerCvPage() { const { t } = useLanguage(); const { data: profile, loading } = useDemo(demoApi.getProfile, []); const [uploading, setUploading] = useState(false); const [uploaded, setUploaded] = useState(false); const upload = async (file?: File) => { setUploading(true); await demoApi.uploadCv({ name: file?.name || 'Layan_Alotaibi_CV.pdf', size: file?.size || 2340000 }); setUploading(false); setUploaded(true); }; if (loading || !profile) return <DashboardLayout role="seeker"><LoadingState /></DashboardLayout>; return <DashboardLayout role="seeker"><PageHeader eyebrow="السيرة الذاتية" title="حوّل سيرتك إلى صورة قابلة للفهم." description="نستخرج المعلومات لتراجعها، لا لنقرر بدلاً عنك." /><div className="grid gap-6 lg:grid-cols-[1fr_320px]"><div className="space-y-6"><Card><CardContent className="p-6 md:p-8"><label className={`flex min-h-56 cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed ${uploading ? 'border-accent bg-accent/5' : 'border-primary/30 bg-primary/5'} p-8 text-center`}><input type="file" accept=".pdf,.docx" className="sr-only" onChange={(e) => upload(e.target.files?.[0])} data-testid="input-cv-upload" /><UploadCloud className="h-9 w-9 text-primary" /><p className="mt-4 font-bold">{uploading ? 'جارٍ تحليل السيرة…' : uploaded ? 'تم تحديث السيرة الذاتية' : 'اسحب ملفك هنا أو اختره'}</p><p className="mt-2 text-xs text-muted-foreground">PDF أو DOCX · حتى 10MB</p>{uploading && <div className="mt-5 h-1.5 w-48 overflow-hidden rounded-full bg-muted"><div className="h-full w-2/3 animate-pulse rounded-full bg-accent" /></div>}</label></CardContent></Card><Card><CardHeader><CardTitle className="flex items-center gap-2 text-base"><Sparkles className="h-4 w-4 text-primary" />AI extracted profile</CardTitle></CardHeader><CardContent><div className="rounded-xl bg-secondary/60 p-5"><div className="flex items-center justify-between"><span className="text-sm font-bold">مصمم منتجات</span><span className="rounded-full bg-primary/10 px-2 py-1 text-[11px] font-semibold text-primary">مستخرج</span></div><p className="mt-3 text-xs leading-6 text-muted-foreground">مصمم منتجات بخبرة 4 سنوات في بناء تجارب رقمية عربية، مع تركيز على البحث وأنظمة التصميم.</p><div className="mt-4 flex flex-wrap gap-2">{profile.skills.slice(0, 5).map((skill) => <span key={skill.id} className="rounded-md bg-background px-2 py-1 text-[11px]">{skill.name}</span>)}</div></div><p className="mt-4 flex items-start gap-2 text-xs leading-6 text-muted-foreground"><CircleAlert className="mt-0.5 h-4 w-4 shrink-0 text-accent" />{t('review')} {t('decision')}</p></CardContent></Card></div><Card className="h-fit"><CardHeader><CardTitle className="text-base">حالة الملف</CardTitle></CardHeader><CardContent><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-full bg-primary/10 text-primary"><CheckCircle2 className="h-5 w-5" /></div><div><p className="text-sm font-bold">تم التحليل</p><p className="text-xs text-muted-foreground">آخر تحديث: اليوم</p></div></div><div className="mt-6 space-y-3 text-xs"><div className="flex items-center gap-2"><Check className="h-4 w-4 text-primary" />المعلومات الأساسية</div><div className="flex items-center gap-2"><Check className="h-4 w-4 text-primary" />الخبرة والمهارات</div><div className="flex items-center gap-2 text-muted-foreground"><span className="h-4 w-4 rounded-full border border-border" />مراجعة واعتماد</div></div></CardContent></Card></div></DashboardLayout>; }

export function RecommendationsPage() { const { data: matches, loading, error, reload } = useDemo(demoApi.recommendations, []); if (loading) return <DashboardLayout role="seeker"><LoadingState /></DashboardLayout>; if (error || !matches) return <DashboardLayout role="seeker"><FeedbackState error={error} retry={reload} /></DashboardLayout>; return <DashboardLayout role="seeker"><PageHeader eyebrow="الذكاء في خدمتك" title="توصيات لها سبب." description="كل نتيجة هنا قابلة للفهم والمراجعة — وليست حكماً نهائياً على ملاءمتك." /><div className="space-y-5">{matches.map((match) => { const job = [match.jobId === 'j-1' ? 'مصمم تجربة مستخدم أول' : match.jobId === 'j-2' ? 'مدير منتج — منصات الذكاء الاصطناعي' : 'مهندس واجهات أمامية'][0]; return <Card key={match.id}><CardContent className="grid gap-6 p-6 md:grid-cols-[180px_1fr_1fr] md:items-center"><div className="flex items-center gap-4 md:block"><ScoreRing score={match.score} /><div className="md:mt-3"><p className="font-bold">{job}</p><p className="mt-1 text-xs text-muted-foreground">توصية مبنية على ملفك</p></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-wider text-primary">تفصيل التطابق</p><ScoreBreakdown match={match} /></div><div><p className="mb-3 text-xs font-bold uppercase tracking-wider text-primary">ماذا تطابق؟</p><div className="flex flex-wrap gap-2">{match.matchedSkills.map((skill) => <span key={skill.id} className="rounded-md bg-primary/10 px-2.5 py-1.5 text-[11px] font-semibold text-primary">{skill.name}</span>)}</div><p className="mb-2 mt-5 text-xs font-bold text-muted-foreground">فجوات تستحق النظر</p><div className="flex flex-wrap gap-2">{match.missingSkills.map((skill) => <span key={skill.id} className="rounded-md bg-muted px-2.5 py-1.5 text-[11px]">{skill.name}</span>)}</div><Link href={`/jobs/${match.jobId}`} className="mt-5 inline-flex items-center gap-1 text-xs font-bold text-primary" data-testid={`link-recommendation-${match.id}`}>عرض الوظيفة <ArrowUpLeft className="h-3.5 w-3.5" /></Link></div></CardContent></Card>; })}</div><p className="mt-6 rounded-xl bg-accent/10 p-4 text-xs leading-6 text-muted-foreground"><CircleAlert className="me-2 inline h-4 w-4 text-accent" />النتائج دعم لاتخاذ القرار وليست قرار توظيف نهائي.</p></DashboardLayout>; }

const statusLabels: Record<ApplicationStatus, string> = { applied: 'تم التقديم', reviewing: 'قيد المراجعة', shortlisted: 'القائمة المختصرة', interview: 'مقابلة', rejected: 'غير مناسب حالياً', accepted: 'تم القبول' };
export function ApplicationsPage() { const { data, loading, error, reload } = useDemo(demoApi.applications, []); if (loading) return <DashboardLayout role="seeker"><LoadingState /></DashboardLayout>; if (error || !data) return <DashboardLayout role="seeker"><FeedbackState error={error} retry={reload} /></DashboardLayout>; return <DashboardLayout role="seeker"><PageHeader eyebrow="رحلتك" title="طلبات التقديم" description="مكان واحد لتعرف أين وصلت كل فرصة." /><Card><CardContent className="p-0"><div className="hidden grid-cols-[1.6fr_1fr_.8fr_.7fr] gap-4 border-b border-border px-6 py-4 text-xs font-bold text-muted-foreground md:grid"><span>الوظيفة</span><span>الشركة</span><span>تاريخ التقديم</span><span>الحالة</span></div>{data.map((item) => <div key={item.id} className="grid gap-3 border-b border-border px-5 py-5 last:border-0 md:grid-cols-[1.6fr_1fr_.8fr_.7fr] md:items-center md:px-6"><div><Link href={`/jobs/${item.job.id}`} className="text-sm font-bold hover:text-primary" data-testid={`link-application-job-${item.id}`}>{item.job.title}</Link><p className="mt-1 text-xs text-muted-foreground md:hidden">{item.job.company.name} · {item.appliedAt}</p></div><p className="hidden text-xs text-muted-foreground md:block">{item.job.company.name}</p><p className="hidden text-xs text-muted-foreground md:block">{item.appliedAt}</p><span className="w-fit rounded-full bg-primary/10 px-2.5 py-1 text-[11px] font-semibold text-primary" data-testid={`status-application-${item.id}`}>{statusLabels[item.status]} · {item.matchScore}%</span></div>)}</CardContent></Card></DashboardLayout>; }

export function CompanyDashboardPage() { const { data: jobs, loading } = useDemo(demoApi.getCompanyJobs, []); const { data: candidates } = useDemo(() => demoApi.candidates('j-1'), []); if (loading) return <DashboardLayout role="company"><LoadingState /></DashboardLayout>; const metrics: Array<[string, string | number, LucideIcon]> = [['الوظائف النشطة', jobs?.length || 0, BriefcaseBusiness], ['طلبات التقديم', 86, FileText], ['مرشحون جدد', 24, Users], ['متوسط التطابق', '88%', Target]]; return <DashboardLayout role="company"><PageHeader eyebrow="مركز التوظيف" title="صباح الخير، فريق مِداد." description="نظرة سريعة على حركة المواهب والفرص المفتوحة." action={<Link href="/company/jobs/new" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-company-new-job"><Plus className="h-4 w-4" />إضافة وظيفة</Link>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{metrics.map(([label, value, Icon]) => <Card key={label}><CardContent className="p-5"><div className="flex items-center justify-between"><span className="text-xs text-muted-foreground">{label}</span><div className="grid h-9 w-9 place-items-center rounded-lg bg-primary/10 text-primary"><Icon className="h-4 w-4" /></div></div><p className="mt-5 text-3xl font-bold">{value}</p><p className="mt-2 text-[11px] text-primary">+12% هذا الشهر</p></CardContent></Card>)}</div><div className="mt-10 grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><Card><CardHeader className="flex-row items-center justify-between"><CardTitle className="text-base">أفضل المرشحين الآن</CardTitle><Link href="/company/jobs/j-1/candidates" className="text-xs font-bold text-primary" data-testid="link-company-candidates">عرض القائمة</Link></CardHeader><CardContent className="space-y-3">{candidates?.map((candidate) => <div key={candidate.id} className="flex items-center gap-3 rounded-xl border border-border p-3"><div className="grid h-10 w-10 place-items-center rounded-full bg-secondary text-xs font-bold text-primary">{candidate.name.slice(0, 2)}</div><div className="flex-1"><p className="text-sm font-bold">{candidate.name}</p><p className="text-xs text-muted-foreground">{candidate.headline}</p></div><div className="text-end"><p className="text-sm font-bold text-primary">{candidate.score}%</p><p className="text-[10px] text-muted-foreground">مطابقة</p></div></div>)}</CardContent></Card><Card><CardHeader><CardTitle className="text-base">آخر النشاطات</CardTitle></CardHeader><CardContent className="space-y-5">{['تقدم مرشح جديد على مصمم تجربة مستخدم أول', 'تم تحديث وصف وظيفة مدير المنتج', 'مرشح جديد وصل إلى القائمة المختصرة'].map((text, i) => <div key={text} className="flex gap-3"><div className="mt-1 h-2 w-2 rounded-full bg-accent" /><div><p className="text-xs leading-5">{text}</p><p className="mt-1 text-[10px] text-muted-foreground">منذ {i + 1} ساعة</p></div></div>)}</CardContent></Card></div><div className="mt-8"><p className="mb-4 text-sm font-bold">وظائفك النشطة</p><div className="grid gap-4 md:grid-cols-2">{jobs?.map((job) => <JobCard key={job.id} job={job} />)}</div></div></DashboardLayout>; }

export function CompanyProfilePage() { const { data, loading } = useDemo(demoApi.company, []); const [saved, setSaved] = useState(false); const [company, setCompany] = useState<Company | null>(null); if (loading || (!data && !company)) return <DashboardLayout role="company"><LoadingState /></DashboardLayout>; const value = company || data!; return <DashboardLayout role="company"><PageHeader eyebrow="هوية الشركة" title="ملف يعرّف الناس بكم." description="معلومات واضحة تساعد المرشحين على اختيار البيئة المناسبة لهم." action={<Button onClick={() => setSaved(true)} data-testid="button-save-company-profile">{saved ? 'تم الحفظ' : 'حفظ التغييرات'}</Button>} /><Card><CardContent className="grid gap-5 p-6 md:grid-cols-2 md:p-8"><div className="md:col-span-2 flex items-center gap-4 border-b border-border pb-6"><div className="grid h-16 w-16 place-items-center rounded-2xl bg-secondary text-primary"><Building2Icon /></div><div><p className="text-lg font-bold">{value.name}</p><p className="text-xs text-muted-foreground">{value.industry} · {value.location}</p></div></div><Field label="اسم الشركة" value={value.name} onChange={(v) => setCompany({ ...value, name: v })} /><Field label="المجال" value={value.industry} onChange={(v) => setCompany({ ...value, industry: v })} /><Field label="الموقع" value={value.location} onChange={(v) => setCompany({ ...value, location: v })} /><Field label="الموقع الإلكتروني" value={value.website} onChange={(v) => setCompany({ ...value, website: v })} /><div className="md:col-span-2"><Field label="عن الشركة" value={value.description} onChange={(v) => setCompany({ ...value, description: v })} multiline /></div></CardContent></Card></DashboardLayout>; }
function Building2Icon() { return <Building2 className="h-7 w-7" />; }

export function CompanyJobsPage() { const { data, loading, error, reload } = useDemo(demoApi.getCompanyJobs, []); if (loading) return <DashboardLayout role="company"><LoadingState /></DashboardLayout>; if (error || !data) return <DashboardLayout role="company"><FeedbackState error={error} retry={reload} /></DashboardLayout>; return <DashboardLayout role="company"><PageHeader eyebrow="إدارة الفرص" title="وظائفك في مكان واحد." description="تابع أداء كل فرصة وافتح قائمة المرشحين الأقرب." action={<Link href="/company/jobs/new" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-jobs-add"><Plus className="h-4 w-4" />إضافة وظيفة</Link>} /><div className="space-y-3">{data.map((job) => <Card key={job.id}><CardContent className="flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div><Link href={`/company/jobs/${job.id}`} className="font-bold hover:text-primary" data-testid={`link-company-job-${job.id}`}>{job.title}</Link><p className="mt-1 text-xs text-muted-foreground">{job.location} · {job.applicants} متقدم</p></div><div className="flex items-center gap-3"><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[11px] font-semibold text-primary">نشطة</span><Link href={`/company/jobs/${job.id}/candidates`} className="rounded-lg border border-border px-3 py-2 text-xs font-bold" data-testid={`link-job-candidates-${job.id}`}>المرشحون</Link><Link href={`/company/jobs/${job.id}`} className="rounded-lg bg-secondary px-3 py-2 text-xs font-bold" data-testid={`link-manage-job-${job.id}`}>إدارة</Link></div></CardContent></Card>)}</div></DashboardLayout>; }

export function NewJobPage() { const [, setLocation] = useLocation(); const [title, setTitle] = useState(''); const [description, setDescription] = useState(''); const [industry, setIndustry] = useState('تقنية المعلومات'); const [location, setJobLocation] = useState('الرياض، السعودية'); const [submitted, setSubmitted] = useState(false); const create = async (e: React.FormEvent) => { e.preventDefault(); await demoApi.createJob({ title, description, industry, location, requiredSkills: [], preferredSkills: [], deadline: '2025-07-30' }); setSubmitted(true); setTimeout(() => setLocation('/company/jobs'), 500); }; return <DashboardLayout role="company"><PageHeader eyebrow="فرصة جديدة" title="اكتب الدور الذي تريد أن ينضم إليه." description="الوصف الواضح يجذب الأشخاص المناسبين ويجعل المطابقة أدق." /><form onSubmit={create} className="space-y-6"><Card><CardContent className="grid gap-5 p-6 md:p-8"><div className="md:col-span-2"><Field label="المسمى الوظيفي" value={title} onChange={setTitle} placeholder="مثال: مدير منتج أول" /></div><div className="grid gap-5 md:grid-cols-2"><label className="text-sm font-semibold">المجال<select value={industry} onChange={(e) => setIndustry(e.target.value)} className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-job-industry"><option>تقنية المعلومات</option><option>التقنية المالية</option><option>التسويق</option><option>الاستشارات</option></select></label><Field label="الموقع" value={location} onChange={setJobLocation} placeholder="المدينة أو عن بعد" /></div><Field label="وصف الوظيفة" value={description} onChange={setDescription} placeholder="ما الذي سيقوم به الشخص؟ وما الذي سيجعل هذه الفرصة مميزة؟" multiline /></CardContent></Card><Card><CardHeader><CardTitle className="text-base">تفاصيل الدور</CardTitle></CardHeader><CardContent className="grid gap-5 md:grid-cols-3"><label className="text-sm font-semibold">نوع العقد<select className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-job-contract"><option>دوام كامل</option><option>دوام جزئي</option><option>عقد مستقل</option></select></label><label className="text-sm font-semibold">الخبرة<select className="mt-2 h-10 w-full rounded-md border border-input bg-background px-3 text-sm" data-testid="select-job-experience"><option>متوسط</option><option>مبتدئ</option><option>خبير</option></select></label><Field label="آخر موعد" value="2025-07-30" onChange={() => undefined} /></CardContent></Card><div className="flex justify-end gap-3"><Link href="/company/jobs" className="rounded-lg border border-border px-5 py-2.5 text-sm font-semibold" data-testid="link-cancel-job">إلغاء</Link><Button type="submit" disabled={!title || !description} data-testid="button-publish-job">{submitted ? 'تم النشر' : 'نشر الوظيفة'}</Button></div></form></DashboardLayout>; }

export function CompanyJobDetailPage() { const { id } = useParams<{ id: string }>(); const { data: job, loading } = useDemo(() => demoApi.getJob(id || ''), [id]); const [, setLocation] = useLocation(); const [deleted, setDeleted] = useState(false); if (loading || !job) return <DashboardLayout role="company"><LoadingState /></DashboardLayout>; return <DashboardLayout role="company"><PageHeader eyebrow="إدارة الوظيفة" title={job.title} description={`${job.location} · ${job.applicants} متقدم`} action={<div className="flex gap-2"><Link href={`/company/jobs/${job.id}/candidates`} className="rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-detail-candidates">عرض المرشحين</Link><Button variant="outline" onClick={async () => { await demoApi.deleteJob(job.id); setDeleted(true); setLocation('/company/jobs'); }} data-testid="button-delete-job">حذف</Button></div>} />{deleted ? <FeedbackState /> : <div className="grid gap-6 lg:grid-cols-[1fr_300px]"><Card><CardContent className="prose prose-sm max-w-none p-6"><h2>عن الدور</h2><p>{job.description}</p><h2>المهارات</h2><div className="not-prose flex flex-wrap gap-2">{job.requiredSkills.map((skill) => <span key={skill.id} className="rounded-md bg-primary/10 px-3 py-1.5 text-xs font-semibold text-primary">{skill.name}</span>)}</div></CardContent></Card><div className="space-y-4"><Card><CardContent className="p-5"><p className="text-xs text-muted-foreground">حالة النشر</p><div className="mt-2 flex items-center gap-2 text-sm font-bold text-primary"><span className="h-2 w-2 rounded-full bg-primary" />نشطة</div><div className="mt-5 space-y-3 border-t border-border pt-4 text-xs"><div className="flex justify-between"><span className="text-muted-foreground">التقديمات</span><span>{job.applicants}</span></div><div className="flex justify-between"><span className="text-muted-foreground">آخر موعد</span><span>{job.deadline}</span></div></div></CardContent></Card></div></div>}</DashboardLayout>; }

export function CandidatesPage() { const { id } = useParams<{ id: string }>(); const { data, loading, error, reload } = useDemo(() => demoApi.candidates(id || 'j-1'), [id]); const [sort, setSort] = useState('score'); const candidates = useMemo(() => [...(data || [])].sort((a, b) => sort === 'score' ? b.score - a.score : a.name.localeCompare(b.name)), [data, sort]); if (loading) return <DashboardLayout role="company"><LoadingState /></DashboardLayout>; if (error || !data) return <DashboardLayout role="company"><FeedbackState error={error} retry={reload} /></DashboardLayout>; return <DashboardLayout role="company"><PageHeader eyebrow="ذكاء التوظيف" title="المرشحون الأقرب للدور." description="ترتيب يساعدك على بدء الحوار — لا يستبدل المقابلة أو التقييم البشري." action={<select value={sort} onChange={(e) => setSort(e.target.value)} className="h-10 rounded-lg border border-input bg-card px-3 text-xs font-semibold" data-testid="select-candidate-sort"><option value="score">الأعلى تطابقاً</option><option value="name">الاسم</option></select>} /><div className="space-y-4">{candidates.map((candidate) => <Card key={candidate.id}><CardContent className="grid gap-6 p-5 md:grid-cols-[1.15fr_1fr_1fr] md:items-center"><div className="flex items-center gap-3"><div className="grid h-12 w-12 place-items-center rounded-full bg-secondary font-bold text-primary">{candidate.name.slice(0, 2)}</div><div><Link href={`/company/jobs/${id || 'j-1'}/candidates/${candidate.id}`} className="font-bold hover:text-primary" data-testid={`link-candidate-${candidate.id}`}>{candidate.name}</Link><p className="mt-1 text-xs text-muted-foreground">{candidate.headline}</p><span className="mt-2 inline-block rounded-full bg-primary/10 px-2 py-1 text-[10px] font-semibold text-primary">{statusLabels[candidate.status as ApplicationStatus]}</span></div></div><div><div className="mb-3 flex items-center justify-between"><span className="text-xs font-bold text-muted-foreground">التطابق العام</span><span className="text-lg font-bold text-primary">{candidate.score}%</span></div><ScoreBreakdown match={{ id: candidate.id, jobId: id || '', score: candidate.score, breakdown: candidate.breakdown, matchedSkills: candidate.matchedSkills, missingSkills: candidate.missingSkills, relevantExperience: [], relevantProjects: [], explanation: '' }} /></div><div><p className="mb-2 text-xs font-bold text-primary">المهارات المطابقة</p><div className="flex flex-wrap gap-1.5">{candidate.matchedSkills.map((skill) => <span key={skill.id} className="rounded bg-primary/10 px-2 py-1 text-[10px] text-primary">{skill.name}</span>)}</div><p className="mb-2 mt-4 text-xs font-bold text-muted-foreground">فجوات</p><div className="flex flex-wrap gap-1.5">{candidate.missingSkills.map((skill) => <span key={skill.id} className="rounded bg-muted px-2 py-1 text-[10px]">{skill.name}</span>)}</div></div></CardContent></Card>)}</div><p className="mt-6 rounded-xl bg-accent/10 p-4 text-xs leading-6 text-muted-foreground"><CircleAlert className="me-2 inline h-4 w-4 text-accent" />{`نتائج HiMe AI ${'دعم لاتخاذ القرار وليست قرار توظيف نهائي.'}`}</p></DashboardLayout>; }

function AdminLayout({ children }: { children: ReactNode }) { return <RoleShell role="admin">{children}</RoleShell>; }
export function AdminDashboardPage() { const { data, loading } = useDemo(demoApi.stats, []); if (loading || !data) return <AdminLayout><LoadingState /></AdminLayout>; return <AdminLayout><PageHeader eyebrow="الإدارة" title="صورة المنصة." description="ملخص تشغيلي للبيئة التجريبية." /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{Object.entries(data).map(([label, value]) => <Card key={label}><CardContent className="p-5"><p className="text-xs text-muted-foreground">{label === 'candidates' ? 'الباحثون' : label === 'companies' ? 'الشركات' : label === 'jobs' ? 'الوظائف' : 'الطلبات'}</p><p className="mt-4 text-3xl font-bold text-primary">{value.toLocaleString()}</p><p className="mt-2 text-[11px] text-muted-foreground">إجمالي مسجل</p></CardContent></Card>)}</div><Card className="mt-8"><CardHeader><CardTitle className="text-base">مؤشر النشاط</CardTitle></CardHeader><CardContent><div className="flex h-40 items-end gap-3">{[32, 48, 44, 63, 57, 74, 68, 86, 78, 92, 82, 96].map((height, i) => <div key={i} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t bg-primary/70" style={{ height: `${height}%` }} /><span className="text-[9px] text-muted-foreground">{i + 1}</span></div>)}</div></CardContent></Card></AdminLayout>; }
export function AdminCompaniesPage() { const { data, loading, error, reload } = useDemo(demoApi.listCompanies, []); return <AdminTablePage title="الشركات" eyebrow="إدارة المنصة" loading={loading} error={error} reload={reload} headers={['الشركة', 'المجال', 'الموقع', 'الحالة']} rows={(data || []).map((company) => [company.name, company.industry, company.location, company.verified ? 'موثقة' : 'قيد المراجعة'])} />; }
export function AdminCandidatesPage() { return <AdminTablePage title="الباحثون عن عمل" eyebrow="إدارة المنصة" headers={['الاسم', 'المجال', 'اكتمال الملف', 'الحالة']} rows={['ليان العتيبي', 'سارة الحربي', 'عمر الغامدي'].map((name, i) => [name, ['تصميم المنتجات', 'البحث', 'الهندسة'][i], `${82 - i * 7}%`, 'نشط'])} />; }
export function AdminJobsPage() { const { data, loading, error, reload } = useDemo(() => demoApi.listJobs(), []); return <AdminTablePage title="الوظائف" eyebrow="إدارة المنصة" loading={loading} error={error} reload={reload} headers={['الدور', 'الشركة', 'المجال', 'الحالة']} rows={(data || []).map((job) => [job.title, job.company.name, job.industry, 'نشطة'])} />; }
export function AdminApplicationsPage() { const { data, loading, error, reload } = useDemo(demoApi.applications, []); return <AdminTablePage title="طلبات التقديم" eyebrow="إدارة المنصة" loading={loading} error={error} reload={reload} headers={['الوظيفة', 'الباحث', 'التطابق', 'الحالة']} rows={(data || []).map((item) => [item.job.title, 'ليان العتيبي', `${item.matchScore}%`, statusLabels[item.status]])} />; }
function AdminTablePage({ title, eyebrow, headers, rows, loading = false, error = '', reload }: { title: string; eyebrow: string; headers: string[]; rows: string[][]; loading?: boolean; error?: string; reload?: () => void }) { return <AdminLayout><PageHeader eyebrow={eyebrow} title={title} description="عرض مبسط لإدارة بيانات المنصة." />{loading ? <LoadingState /> : error ? <FeedbackState error={error} retry={reload} /> : <Card><CardContent className="overflow-x-auto p-0"><table className="w-full min-w-[620px] text-start text-sm"><thead className="border-b border-border bg-muted/50 text-xs text-muted-foreground"><tr>{headers.map((header) => <th key={header} className="px-6 py-4 font-bold">{header}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, index) => <tr key={index} className="border-b border-border last:border-0"><>{row.map((cell, cellIndex) => <td key={cellIndex} className="px-6 py-4">{cellIndex === 0 ? <span className="font-semibold">{cell}</span> : <span className="text-muted-foreground">{cell}</span>}</td>)}</></tr>) : <tr><td colSpan={headers.length} className="px-6 py-12 text-center text-muted-foreground">لا توجد بيانات</td></tr>}</tbody></table></CardContent></Card>}</AdminLayout>; }